/** Decide whether the runner should even attempt a branch push for a job. */
export function evaluateBranchPushEligibility(input: BranchPushEligibilityInput): BranchPushEligibilityResult {
  if (!input.allowBranchPush) return { attemptPush: false, reason: "Branch push disabled" };
  if (!input.hasArtifact) return { attemptPush: false, reason: "No patch artifact" };
  if (!input.branchName) return { attemptPush: false, reason: "No branch name" };
  if (input.commandPolicy === SANDBOX_PATCH_NO_PUSH) {
    return { attemptPush: false, reason: "commandPolicy restricts branch push" };
  }
  return { attemptPush: true };
}

export interface ApprovalArtifactState {
  validationStatus: string;
  riskLevel: string;
}

/** Decide whether a patch can be pushed without explicit King approval. */
export function shouldPushWithoutApproval(artifact: ApprovalArtifactState): boolean {
  return artifact.riskLevel === "LOW" && artifact.validationStatus === "PENDING";
}

export function isAutoPatchEligible(ctx: RiskPolicyContext): RiskPolicyResult {
  if (ctx.todayJobCount >= ctx.maxDailyJobs) {
    return { eligible: false, skippedReason: "Daily auto patch limit reached", auditAction: "auto_patch_daily_limit_blocked" };
  }
  if (ctx.candidate.confidence < ctx.minConfidence) {
    return { eligible: false, skippedReason: `Confidence ${ctx.candidate.confidence} below threshold ${ctx.minConfidence}`, auditAction: "living_loop_auto_sandbox_patch_skipped" };
  }
  if (ctx.candidate.riskLevel !== "LOW") {
    return { eligible: false, skippedReason: `Risk level ${ctx.candidate.riskLevel} is not LOW`, auditAction: "auto_patch_risk_policy_blocked" };
  }
  if (!ctx.runnerOnline) {
    return { eligible: false, skippedReason: "No online runner available", auditAction: "living_loop_auto_sandbox_patch_skipped" };
  }
  if (!ctx.workOrder.projectId) {
    return { eligible: false, skippedReason: "Work order not linked to project", auditAction: "living_loop_auto_sandbox_patch_skipped" };
  }
  if (ctx.activeJobCount > 0) {
    return { eligible: false, skippedReason: "Active automation job already exists", auditAction: "living_loop_auto_sandbox_patch_skipped" };
  }
  if (ctx.recentJobCount > 0) {
    return { eligible: false, skippedReason: "Auto patch job within cooldown", auditAction: "auto_patch_cooldown_blocked" };
  }

  // Check proposedAction hints for blocked paths
  const action = ctx.candidate.proposedAction as any;
  if (action && typeof action === "object") {
    const hints: string[] = [];
    if (Array.isArray(action.fileHints)) hints.push(...action.fileHints);
    if (Array.isArray(action.expectedFiles)) hints.push(...action.expectedFiles);

    for (const hint of hints) {
      const lowerHint = hint.toLowerCase();
      if (BLOCKED_PATHS.some(b => lowerHint.includes(b))) {
        return { eligible: false, skippedReason: `Blocked path hint detected: ${hint}`, auditAction: "auto_patch_risk_policy_blocked" };
      }
    }
  }

  return { eligible: true };

export function orderByPolicy(providers: AIProviderConfig[], taskMode: TaskMode, costMode: AICostMode): AIProviderConfig[] {
  const taskOrder = TASK_MODE_PROVIDER_ORDER[taskMode];
  const ranked = [...providers].sort((a, b) => {
    const taskRank = rankInList(a.id, taskOrder) - rankInList(b.id, taskOrder);
    const costRank = costModeRank(a, costMode) - costModeRank(b, costMode);
    return costRank || taskRank || a.priority - b.priority || a.name.localeCompare(b.name);
  });

  return ranked;
}

export function supportsRequiredCapabilities(provider: AIProviderConfig, required: RequiredAICapabilities = {}): boolean {
  if (required.chat !== false && !provider.supportsChat) return false;
  if (required.tools && !provider.supportsTools) return false;
  if (required.vision && !provider.supportsVision) return false;
  if (required.jsonMode && !provider.supportsJsonMode) return false;
  return true;
}

async function resolveCostMode(agentPreference?: string | null): Promise<AICostMode> {
  if (agentPreference === "LOW") return "low";
  if (agentPreference === "QUALITY") return "quality";
  if (agentPreference === "BALANCED") return "balanced";
  const settingValue = await getSettingValue("AI_COST_MODE", env.AI_COST_MODE);
  if (["low", "balanced", "quality"].includes(settingValue)) return settingValue as AICostMode;
  return env.AI_COST_MODE;
}

function rankInList(id: string, values: string[]): number {
  const index = values.indexOf(id);
  return index === -1 ? 1000 : index;
}

function costModeRank(provider: AIProviderConfig, costMode: AICostMode): number {
  const costRank = { FREE: 0, LOW: 1, MEDIUM: 2, HIGH: 3, PREMIUM: 4 }[provider.costTier];
  if (costMode === "low") return costRank;
  if (costMode === "quality") return 4 - costRank;
  return Math.abs(costRank - 2);
}

