export async function runCommand(
  command: string,
  args: string[],
  opts: RunCommandOptions
): Promise<ExecutionResult> {
  // 1. Validate against allowlist
  const validation = validateCommand(command, args, opts.jobAllowedCommands);
  if (!validation.allowed) {
    return {
      exitCode: -1,
      stdout: "",
      stderr: "",
      output: `[BLOCKED] ${validation.reason}`,
      durationMs: 0,
      cwd: path.resolve(opts.cwd ?? opts.workspaceRoot),
      allowed: false,
      timedOut: false,
      outputTruncated: false,
      blockReason: validation.reason
    };
  }

  // 2. Assert cwd is inside workspace
  const effectiveCwd = opts.cwd ?? opts.workspaceRoot;
  assertCwdInWorkspace(opts.workspaceRoot, effectiveCwd);

  const startedAt = Date.now();
  const timeout = opts.timeoutMs ?? getCommandTimeoutMs(opts.env);

  return new Promise((resolve) => {
    let stdout = "";
    let stderr = "";
    let timedOut = false;

    const child = spawn(command, args, {
      cwd: path.resolve(effectiveCwd),
      env: buildValidationChildEnv(opts.env).env,
      shell: false,           // NEVER shell: true
      timeout
    });

function validateGitArgs(args: string[]): boolean {
  const sub = args[0] ?? "INVALID";
  if (!allowedGitSubcommands.has(sub)) return false;

  switch (sub) {
    case "status": case "log": return true;
    case "diff": return args.length <= 3;
    case "show": return args.length <= 2;
    case "checkout": {
      if (args[1] !== "-b") return false;
      const branch = args[2];
      if (!branch) return false;
      return SAFE_BRANCH_PATTERN.test(branch);
    }
    case "add": {
      if (args.length < 2) return false;
      return args.slice(1).every((a) => !a.startsWith("../") && !a.startsWith("/") && a !== "--");
    }
    case "commit": {
      if (args[1] !== "-m" || !args[2]) return false;
      const msg = args[2];
      return !/[`$<>|;&]/.test(msg) && msg.length <= 200;
    }
    case "push": {
      if (args[1] !== "origin") return false;
      const branch = args[2];
      if (!branch || isProtectedBranch(branch)) return false;
      if (!SAFE_BRANCH_PATTERN.test(branch)) return false;
      if (args.length > 3) return false;
      return true;
    }
    default: return false;
  }
}
